(() => {
  const form=document.getElementById('entryForm');
  let drafts=[],busy=false,viewUrls=[];
  const box=document.createElement('div');box.className='field receipts';
  box.innerHTML='<label for="receiptFiles">上传截图，自动填写账目</label><input id="receiptFiles" type="file" accept="image/png,image/jpeg,image/webp" multiple><p class="receipt-help">自动提取实付金额、日期、商品及分类，核对后保存。同日订单最多5张，每张10MB以内。图片在设备内识别，保存后随账目同步到私有云端；首次使用需下载识别组件。</p><div id="receiptPreviews"></div><button type="button" id="receiptRetry" hidden>重新识别截图</button><p id="receiptStatus" role="status" aria-live="polite"></p>';
  form.insertBefore(box,form.querySelector('.field'));
  const dateBox=document.createElement('div');dateBox.className='field';dateBox.innerHTML='<label for="entryDate">交易日期</label><input id="entryDate" type="date" required>';form.insertBefore(dateBox,form.querySelector('.submit'));const dateInput=document.getElementById('entryDate');const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());dateInput.value=today();
  const input=document.getElementById('receiptFiles'),previews=document.getElementById('receiptPreviews'),status=document.getElementById('receiptStatus'),submit=form.querySelector('.submit');
  const dialog=document.createElement('dialog');dialog.className='receipt-dialog';dialog.innerHTML='<div class="receipt-toolbar"><h2>账单截图</h2><button type="button" id="closeReceipts">关闭</button></div><div id="receiptGallery"></div>';document.body.append(dialog);
  document.getElementById('closeReceipts').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{viewUrls.forEach(URL.revokeObjectURL);viewUrls=[];document.getElementById('receiptGallery').replaceChildren()});
  const openDB=()=>new Promise((resolve,reject)=>{const r=indexedDB.open('blank-finance-receipts',1);r.onupgradeneeded=()=>r.result.createObjectStore('images',{keyPath:'id'});r.onerror=()=>reject(r.error);r.onblocked=()=>reject(Error('请关闭其他记账页面后重试'));r.onsuccess=()=>resolve(r.result)});
  async function storeImages(images){const db=await openDB();try{await new Promise((ok,no)=>{const t=db.transaction('images','readwrite');t.oncomplete=ok;t.onerror=()=>no(t.error);t.onabort=()=>no(t.error);images.forEach(i=>t.objectStore('images').put(i))})}finally{db.close()}}
  async function getLocalImage(id){const db=await openDB();try{return await new Promise((ok,no)=>{const r=db.transaction('images').objectStore('images').get(id);r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error)})}finally{db.close()}}
  async function getImage(id){let file=await getLocalImage(id);if(file)return file;const r=await fetch('/api/receipts/'+encodeURIComponent(id),{cache:'no-store',credentials:'same-origin'});if(!r.ok)return null;const ref=state.entries.flatMap(e=>e.receipts||[]).find(x=>x.id===id);file={id,name:ref?.name||'账单.jpg',blob:await r.blob()};await storeImages([file]);return file}
  window.financeReceipts={local:getLocalImage,get:getImage};
  async function dropImages(ids){if(!ids.length)return;const db=await openDB();try{await new Promise((ok,no)=>{const t=db.transaction('images','readwrite');t.oncomplete=ok;t.onerror=()=>no(t.error);ids.forEach(id=>t.objectStore('images').delete(id))})}finally{db.close()}}
  function drawDrafts(){previews.replaceChildren();drafts.forEach((d,i)=>{const tile=document.createElement('div');tile.className='receipt-tile';const img=document.createElement('img');img.src=d.url;img.alt=d.name;const label=document.createElement('span');label.textContent=d.ocr?.amount?money(d.ocr.amount)+' · '+d.name:d.name;const remove=document.createElement('button');remove.type='button';remove.textContent='移除';remove.disabled=busy;remove.onclick=()=>{URL.revokeObjectURL(d.url);drafts.splice(i,1);drawDrafts();applyData()};tile.append(img,label,remove);if(d.ocr){const details=document.createElement('details'),summary=document.createElement('summary'),text=document.createElement('p');summary.textContent='查看识别原文';text.textContent=d.ocr.text;details.append(summary,text);tile.append(details)}previews.append(tile)});document.getElementById('receiptRetry').hidden=!drafts.length;document.getElementById('receiptRetry').disabled=busy}
  function applyData(){if(!drafts.length){document.getElementById('moneyInput').value='';document.getElementById('note').value='';status.textContent='';return}const data=drafts.map(d=>d.ocr),complete=data.every(d=>d?.amount>0);document.getElementById('moneyInput').value=complete?(data.reduce((sum,d)=>sum+Math.round(d.amount*100),0)/100).toFixed(2):'';const parsed=data.filter(Boolean);const cats=[...new Set(parsed.map(d=>d.category))];if(cats.length&&kind==='expense')document.getElementById('category').value=cats.length===1?cats[0]:'混合支出';document.getElementById('note').value=parsed.map(d=>d.note).join('；').slice(0,1000);const dates=[...new Set(parsed.map(d=>d.date).filter(Boolean))];if(dates.length===1)dateInput.value=dates[0];else if(dates.length>1)dateInput.value='';const accounts=[...new Set(parsed.map(d=>d.account).filter(Boolean))];if(accounts.length===1)document.getElementById('account').value=accounts[0];status.textContent=(complete?'已自动填写实付金额与说明，请核对后保存。':'部分截图未识别出实付金额，可重新识别或补填。')+(dates.length>1?'截图日期不同，请分开保存或选择合并日期。':'')+(parsed.some(d=>!d.account)?'微信支付可能扣银行卡，请确认实际账户。':'')}
  async function scan(d,i){status.textContent=`正在识别第${i+1}张…`;d.ocr=await recognizeFinanceReceipt(d.blob,msg=>status.textContent=`第${i+1}张 · ${msg}`)}
  async function prepare(file){
    if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('请选择PNG、JPG或WebP图片');
    if(file.size>10*1024*1024)throw Error('单张截图不能超过10MB');
    const bitmap=await createImageBitmap(file);try{
      if(bitmap.width*bitmap.height>60000000)throw Error('图片尺寸过大，请裁剪后再上传');
      const scale=Math.min(1,3000/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);
      const blob=await new Promise(r=>canvas.toBlob(r,'image/jpeg',.9));if(!blob)throw Error('图片处理失败');return {id:'receipt-'+crypto.randomUUID(),name:file.name,blob,url:URL.createObjectURL(blob)};
    }finally{bitmap.close()}
  }
  input.onchange=async()=>{if(busy)return;const files=[...input.files];input.value='';if(files.length+drafts.length>5){status.textContent='每笔记录最多5张截图，请先移除多余图片。';return}busy=true;submit.disabled=true;input.disabled=true;status.textContent='正在处理截图…';const errors=[];for(const f of files){try{const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',await f.arrayBuffer()))).join('-');if(drafts.some(d=>d.hash===hash)){errors.push('已跳过重复截图');continue}const d=await prepare(f);d.hash=hash;drafts.push(d);drawDrafts();await scan(d,drafts.length-1);if(d.ocr.orderId&&drafts.some(x=>x!==d&&x.ocr?.orderId===d.ocr.orderId)){drafts.pop();URL.revokeObjectURL(d.url);errors.push('同一订单的重复截图已跳过')}}catch(e){errors.push(f.name+'：'+(e.message||'无法读取图片'))}}busy=false;submit.disabled=false;input.disabled=false;drawDrafts();applyData();if(errors.length)status.textContent+=' '+errors.join('；')};
  document.getElementById('receiptRetry').onclick=async()=>{if(busy)return;busy=true;submit.disabled=true;input.disabled=true;drawDrafts();try{for(let i=0;i<drafts.length;i++)await scan(drafts[i],i);applyData()}catch{status.textContent='识别失败，请检查网络后重试；也可填写金额后保存截图。'}finally{busy=false;submit.disabled=false;input.disabled=false;drawDrafts()}};
  // Persist images first, then commit a single financial update. A storage failure never reports success.
  form.onsubmit=async e=>{e.preventDefault();if(busy||!form.reportValidity())return;const amount=Number(document.getElementById('moneyInput').value);if(!Number.isFinite(amount)||amount<=0){status.textContent='请填写大于0的金额。';return}busy=true;submit.disabled=true;input.disabled=true;drawDrafts();const previous=structuredClone(state);let committed=false;
    try{if(drafts.length)await storeImages(drafts.map(({id,name,blob})=>({id,name,blob})));const account=document.getElementById('account').value;const entry={id:'local-'+crypto.randomUUID(),date:dateInput.value,kind,amount,category:document.getElementById('category').value,account,note:document.getElementById('note').value.trim(),receipts:drafts.map(({id,name})=>({id,name}))};state.entries.unshift(entry);if(account==='银行卡')state.bank+=kind==='income'?amount:-amount;if(account==='微信')state.wechat+=kind==='income'?amount:-amount;if(kind==='expense')state.monthSpend+=amount;localStorage.setItem('blank-finance-v1',JSON.stringify(state));committed=true;
      drafts.forEach(d=>URL.revokeObjectURL(d.url));drafts=[];form.reset();dateInput.value=today();drawDrafts();status.textContent='';fillCats();render();showView('overview');flash(entry.receipts.length?'记录与截图已保存':'已保存到时间轴');
    }catch(err){if(!committed)state=previous;status.textContent=committed?'记录已保存，页面刷新失败，请重新打开。':'保存失败，截图仍保留在表单中。请检查设备存储空间后重试。';console.error('Receipt save failed',err.name)}finally{busy=false;submit.disabled=false;input.disabled=false;drawDrafts()}
  };
  const originalTx=tx;tx=function(e,del=false){const markup=originalTx(e,del);if(!e.receipts?.length)return markup;const btn=`<button type="button" class="receipt-view" data-receipt-entry="${esc(e.id)}">查看截图 · ${e.receipts.length}张</button>`;return markup.replace('</h3>','</h3>'+btn)};
  document.addEventListener('click',async e=>{const button=e.target.closest('[data-receipt-entry]');if(!button)return;const entry=state.entries.find(x=>String(x.id)===button.dataset.receiptEntry);if(!entry)return;dialog.showModal();const gallery=document.getElementById('receiptGallery');gallery.textContent='正在读取截图…';try{const files=await Promise.all(entry.receipts.map(r=>getImage(r.id)));if(!dialog.open)return;gallery.replaceChildren();files.forEach((f,i)=>{if(!f){const p=document.createElement('p');p.textContent='这张截图在当前设备中不存在：'+entry.receipts[i].name;gallery.append(p);return}const url=URL.createObjectURL(f.blob);viewUrls.push(url);const img=document.createElement('img');img.src=url;img.alt=f.name;const a=document.createElement('a');a.href=url;a.download=f.name.replace(/\.[^.]+$/,'')+'.jpg';a.textContent='下载截图 '+(i+1);gallery.append(img,a)})}catch{gallery.textContent='读取失败，请重新打开或检查设备存储设置。'}});
  window.receiptBackup=async()=>{const refs=state.entries.flatMap(e=>e.receipts||[]);return Promise.all(refs.map(async r=>{const f=await getImage(r.id);if(!f)throw Error('截图缺失，无法生成完整备份');const data=await new Promise((ok,no)=>{const reader=new FileReader();reader.onload=()=>ok(reader.result);reader.onerror=no;reader.readAsDataURL(f.blob)});return {id:f.id,name:f.name,data}}))};
  const originalRemove=removeEntry;removeEntry=function(id){const entry=state.entries.find(e=>String(e.id)===String(id));originalRemove(id);if(entry&&!state.entries.some(e=>e.id===entry.id))dropImages((entry.receipts||[]).map(r=>r.id)).catch(()=>{})};
  render();
})();
